// Avito/classified listing fixtures. No external calls. In fixture mode max_items = total emitted records
// (competitor listings + the optional irrelevant control record). DEC-092.
const cfg=$('Set Avito Connector Config').first().json;
const maxItems=Number(cfg.max_items)||6;
const includeControl=(cfg.include_irrelevant_control_fixture!==false);
const competitors=[
  { listing_id:'4379480780', title:'Помощь в получении кредита. Кредитный брокер', description:'Поможем получить кредит физлицам и бизнесу. Работаем по договору, оплата за результат. Сложные случаи, большие суммы.', url:'https://www.avito.ru/moskva/predlozheniya_uslug/pomosch_v_poluchenii_kredita_kreditnyy_broker_4379480780', price:'от 30 000 ₽', location:'Москва', seller_name:'Финанс Групп', seller_url:'https://www.avito.ru/user/abc12300/profile', category:'Предложения услуг', published_at:'', query:'кредитный брокер Москва' },
  { listing_id:'7961833832', title:'Кредитный брокер. Реальная помощь с кредитами', description:'Реальная помощь с кредитами при отказах банков. Консультация от 500 ₽. Москва и область, без предоплаты.', url:'https://www.avito.ru/moskva/predlozheniya_uslug/kreditnyy_broker_realnaya_pomosch_7961833832', price:'от 500 ₽', location:'Москва', seller_name:'КредитЭксперт', seller_url:'https://www.avito.ru/user/def45600/profile', category:'Предложения услуг', published_at:'', query:'помощь в получении кредита Москва' },
  { listing_id:'5521099004', title:'Кредит для бизнеса, ИП и ООО. Кредитный брокер', description:'Привлечение финансирования для ИП и ООО: оборотные кредиты, тендерные займы, банковские гарантии. Поможем с пакетом документов.', url:'https://www.avito.ru/moskva/predlozheniya_uslug/kredit_dlya_biznesa_ip_ooo_5521099004', price:'от 15 000 ₽', location:'Москва', seller_name:'БизнесФинанс Консалт', seller_url:'https://www.avito.ru/user/ghi78900/profile', category:'Предложения услуг', published_at:'', query:'кредитный брокер для бизнеса Москва' },
  { listing_id:'6610233771', title:'Кредит после отказов банков. Поможем получить', description:'Поможем получить кредит после отказов, с просрочками и плохой кредитной историей. Индивидуальный подбор банка.', url:'https://www.avito.ru/moskva/predlozheniya_uslug/kredit_posle_otkazov_bankov_6610233771', price:'', location:'Москва', seller_name:'Одобрение24', seller_url:'https://www.avito.ru/user/jkl01200/profile', category:'Предложения услуг', published_at:'', query:'кредит после отказов Москва' },
  { listing_id:'7188450923', title:'Ипотечный брокер. Рефинансирование ипотеки', description:'Подбор и одобрение ипотеки, рефинансирование действующих кредитов, снижение ставки. Работаем с большинством банков.', url:'https://www.avito.ru/moskva/predlozheniya_uslug/ipotechnyy_broker_refinansirovanie_7188450923', price:'от 10 000 ₽', location:'Москва', seller_name:'Ипотека Просто', seller_url:'https://www.avito.ru/user/mno34500/profile', category:'Предложения услуг', published_at:'', query:'ипотечный брокер рефинансирование Москва' }
];
const control={ listing_id:'3300771199', title:'Продам POS-терминал для эквайринга, б/у', description:'Продаётся б/у POS-терминал для приёма карт. Рабочий, в комплекте блок питания. Самовывоз, Москва.', url:'https://www.avito.ru/moskva/oborudovanie_dlya_biznesa/pos-terminal_dlya_ekvayringa_3300771199', price:'4 500 ₽', location:'Москва', seller_name:'Частное лицо', seller_url:'https://www.avito.ru/user/pqr67800/profile', category:'Оборудование для бизнеса', published_at:'', query:'кредитный брокер Москва' };
let chosen;
if(includeControl){ chosen=competitors.slice(0,Math.max(0,maxItems-1)); if(chosen.length<maxItems) chosen=chosen.concat([control]); }
else { chosen=competitors.slice(0,maxItems); }
return chosen.map((r,i)=>({ json: Object.assign({ _index:i+1, _source:'fixture' }, r) }));

// Deterministic normalization of Avito/classified listings into raw_market_records shape. No LLM, no external calls.
// DEC-092: richer service_hint (credit_broker/business_credit/credit_after_refusals/mortgage_refinance/unknown) +
// concrete ad/semantic keyword phrases + offer/price/terms preserved in manager_note.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function any(b,arr){for(const w of arr){if(b.indexOf(w)>=0)return true;}return false;}
function normUrl(u){u=str(u);if(!u)return '';try{const x=new URL(u.split('#')[0]);x.hostname=(x.hostname||'').toLowerCase();let p=x.pathname||'/';if(p.length>1&&p.endsWith('/'))p=p.slice(0,-1);x.pathname=p;return x.toString();}catch(e){return u.toLowerCase();}}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
function kwHit(blob,tok){ if(tok.length<=3){ return new RegExp('(^|[^а-яёa-z0-9])'+tok+'([^а-яёa-z0-9]|$)','i').test(blob);} return blob.indexOf(tok)>=0; }
// [match token, display label]
const KW=[['кредитный брокер','кредитный брокер'],['ипотечный брокер','ипотечный брокер'],['помощь в получени','помощь в получении кредита'],['помощь с кредит','помощь с кредитом'],['после отказов','после отказов'],['отказах банк','отказы банков'],['плохой кредитн','плохая кредитная история'],['плохая кредитн','плохая кредитная история'],['просрочк','просрочки'],['без предоплаты','без предоплаты'],['оплата за результат','оплата за результат'],['по договору','работа по договору'],['консультаци','консультация'],['подбор банк','подбор банка'],['одобрение','одобрение кредита'],['большие суммы','большие суммы'],['ип','ИП'],['ооо','ООО'],['бизнес-кредит','бизнес-кредит'],['для бизнеса','бизнес-кредит'],['оборотн','оборотные кредиты'],['тендерн','тендерные займы'],['банковск','банковские гарантии'],['рефинансир','рефинансирование'],['снижение ставк','снижение ставки'],['без поручител','без поручителей'],['без справок','без справок']];
function extractKeywords(blob){ const seen={}; const out=[]; for(const pair of KW){ if(kwHit(blob,pair[0]) && !seen[pair[1]]){ seen[pair[1]]=1; out.push(pair[1]); } } return out.join(', '); }
const cfg=$('Set Avito Connector Config').first().json;
const defFocus=low(cfg.service_focus)||'credit_broker';
const region=str(cfg.region)||'Москва/МО';
const items=$input.all().map(i=>i.json).filter(Boolean);
const out=[];
for(const r of items){
  const title=str(r.title);
  const description=str(r.description);
  const price=str(r.price);
  const location=str(r.location)||region;
  const seller_name=str(r.seller_name);
  const seller_url=normUrl(r.seller_url);
  const category=str(r.category);
  const query=str(r.query)|| (Array.isArray(cfg.search_queries)?cfg.search_queries.join('; '):'');
  const listing_id=str(r.listing_id);
  const url=normUrl(r.url||r.source_url);
  const published_at=str(r.published_at);
  const classBlob=(title+' '+description+' '+category).toLowerCase();
  const kwBlob=(title+' '+description+' '+query).toLowerCase();
  const isSell=any(classBlob,['продам','продаётся','продается','б/у','самовывоз','pos-терминал','терминал','оборудование']);
  const isService=!isSell && any(classBlob,['брокер','помощь в получени','помощь с кредит','подбор кредит','одобрение','рефинансир','ипотечный брокер','кредит для бизнеса','кредит после отказов','кредитов','кредит']);
  let record_type_hint, touchpoint_type, predicted_route, predicted_entity_type, next_action, lead_temperature, confidence_score;
  if(isSell && !isService){ record_type_hint='irrelevant'; touchpoint_type='irrelevant_source'; predicted_route='skipped_log'; predicted_entity_type='irrelevant'; next_action='ignore'; lead_temperature='none'; confidence_score=40; }
  else if(isService){ record_type_hint='competitor_activity'; touchpoint_type='competitor_listing'; predicted_route='monitor_queue'; predicted_entity_type='competitor'; next_action='monitor'; lead_temperature='cold'; confidence_score=price?82:74; }
  else { record_type_hint='market_signal'; touchpoint_type='classified_offer'; predicted_route='content_queue'; predicted_entity_type='content_idea'; next_action='create_content'; lead_temperature='cold'; confidence_score=65; }
  const competitor_related=(record_type_hint==='competitor_activity');
  const competitor_name=competitor_related?seller_name:'';
  // service_hint (DEC-092): business_credit only when ИП/ООО/business financing is EXPLICIT (not bare 'бизнесу').
  let service_hint=defFocus;
  if(record_type_hint==='irrelevant')service_hint='unknown';
  else if(any(classBlob,['ипотек','рефинансир','снижение ставк']))service_hint='mortgage_refinance';
  else if(any(classBlob,['для бизнеса','ип и ооо','оборотн','тендерн','банковск','бизнес-кредит']))service_hint='business_credit';
  else if(any(classBlob,['после отказов','отказах банк','просрочк','плохой кредитн','плохая кредитн']))service_hint='credit_after_refusals';
  else service_hint='credit_broker';
  let probable_need='';
  if(record_type_hint!=='irrelevant'){
    if(service_hint==='credit_after_refusals')probable_need='получить кредит после отказов / с плохой КИ';
    else if(service_hint==='business_credit')probable_need='финансирование для бизнеса (ИП/ООО)';
    else if(service_hint==='mortgage_refinance')probable_need='ипотека / рефинансирование, снижение ставки';
    else probable_need='помощь в получении кредита';
  }
  const semantic_keywords=(record_type_hint==='irrelevant')?'':extractKeywords(kwBlob);
  const offer_short=cut(title+(price?(' — '+price):''),140);
  const manager_note=(record_type_hint==='irrelevant')
    ? 'Avito/classified: нерелевантное объявление (не услуга брокера), пропуск.'
    : 'Оффер конкурента: '+offer_short+(price?(' | цена: '+price):' | цена: не указана')+' | условия/семантика: '+(semantic_keywords||'—')+' | площадка/канал: Avito (classifieds).';
  const text_context=cut('Avito объявление: '+title+(price?(' | цена: '+price):'')+' | '+location+(seller_name?(' | продавец: '+seller_name):'')+' | '+description+' | запрос: '+query, 1200);
  const text_hash=hashText(low(title)+'||'+low(description)+'||'+low(price));
  let basekey;
  if(listing_id)basekey='avito_listing_'+listing_id;
  else basekey='avito_url_'+hashText(url||text_context);
  const dedup_key=low(cfg.platform||'avito')+'::'+low(cfg.source_type||'classified')+'::'+basekey;
  out.push({ json: {
    source_type:low(cfg.source_type)||'classified',
    platform:low(cfg.platform)||'avito',
    source_url:url,
    post_url:url,
    profile_url:seller_url,
    profile_name:seller_name,
    author_handle:'',
    seller_name:seller_name,
    published_at:published_at,
    region_hint:region,
    service_hint:service_hint,
    query:query,
    text_context:text_context,
    comment_text:'',
    contact_public:'',
    contact_channel:'',
    dedup_key:dedup_key,
    text_hash:text_hash,
    record_type_hint:record_type_hint,
    touchpoint_type:touchpoint_type,
    lead_intent_hint:'low',
    urgency_hint:'low',
    interest_topic:query,
    probable_need:probable_need,
    competitor_related:competitor_related,
    competitor_name:competitor_name,
    semantic_keywords:semantic_keywords,
    ad_channel_hint:'classifieds',
    confidence_score:confidence_score,
    lead_temperature:lead_temperature,
    next_action:next_action,
    predicted_route:predicted_route,
    predicted_entity_type:predicted_entity_type,
    responsible:'',
    estimated_analysis_cost_usd:0,
    manager_note:manager_note,
    listing_id:listing_id,
    price:price,
    location:location,
    title:title,
    description:description
  }});
}
return out;

// Dedup normalized listings against market_record_registry (by dedup_key) + within batch. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Avito Connector Config').first().json;
const approvalUnique=str(cfg.approval_status_for_unique)||'new';
const dupNext=str(cfg.duplicate_next_action)||'monitor_duplicate';
const recs=$('Normalize Avito Listings').all().map(i=>i.json);
let reg=[];
try{reg=$('Read market_record_registry').all().map(i=>i.json).filter(Boolean);}catch(e){reg=[];}
const regSet=new Set(reg.map(r=>str(r&&r.dedup_key)).filter(Boolean));
const seen=new Set();
const out=[];
for(const r of recs){
  const key=str(r.dedup_key);
  let dedup_status='unique';
  let approval_status=approvalUnique;
  let next_action=str(r.next_action);
  if(key&&regSet.has(key)){
    dedup_status='duplicate_in_registry';approval_status='duplicate';
    next_action=(str(r.record_type_hint)==='irrelevant')?'ignore':dupNext;
  } else if(key&&seen.has(key)){
    dedup_status='duplicate_in_batch';approval_status='duplicate';
    next_action=(str(r.record_type_hint)==='irrelevant')?'ignore':dupNext;
  } else {
    dedup_status='unique';if(key)seen.add(key);
  }
  out.push({ json: Object.assign({}, r, { dedup_status:dedup_status, approval_status:approval_status, next_action:next_action }) });
}
return out;

// Build raw_market_records rows (exactly 40 columns, matching Workflow 07 schema). No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const cfg=$('Set Avito Connector Config').first().json;
const reqId=str(cfg.agent_request_id);
const created=str(cfg.created_at);
const stamp=str(cfg.run_id).replace(/^avito_/,'')||moscowStamp();
const writeDupAudit=(cfg.write_duplicate_audit===true||str(cfg.write_duplicate_audit).toLowerCase()==='true');
const recs=$('Deduplicate Listings').all().map(i=>i.json);
const out=[];let idx=0;
for(const r of recs){
  idx++;
  if(!writeDupAudit && str(r.dedup_status)!=='unique')continue;
  out.push({ json: {
    record_id:'avito_rec_'+stamp+'_'+idx,
    agent_request_id:reqId,
    created_at:created,
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    profile_name:str(r.profile_name),
    author_handle:str(r.author_handle),
    published_at:str(r.published_at),
    region_hint:str(r.region_hint),
    service_hint:str(r.service_hint),
    query:str(r.query),
    text_context:str(r.text_context),
    comment_text:str(r.comment_text),
    contact_public:str(r.contact_public),
    contact_channel:str(r.contact_channel),
    dedup_key:str(r.dedup_key),
    record_type_hint:str(r.record_type_hint),
    touchpoint_type:str(r.touchpoint_type),
    lead_intent_hint:str(r.lead_intent_hint),
    urgency_hint:str(r.urgency_hint),
    interest_topic:str(r.interest_topic),
    probable_need:str(r.probable_need),
    competitor_related:(r.competitor_related===true||str(r.competitor_related).toLowerCase()==='true'),
    competitor_name:str(r.competitor_name),
    semantic_keywords:str(r.semantic_keywords),
    ad_channel_hint:str(r.ad_channel_hint),
    confidence_score:Number(r.confidence_score)||0,
    lead_temperature:str(r.lead_temperature),
    next_action:str(r.next_action),
    responsible:str(r.responsible),
    dedup_status:str(r.dedup_status),
    approval_status:str(r.approval_status),
    approved_by:'',
    approved_at:'',
    estimated_analysis_cost_usd:Number(r.estimated_analysis_cost_usd)||0,
    manager_note:str(r.manager_note),
    notes:'stage_3_3_avito_classifieds_connector'
  }});
}
return out;

// Build market_record_registry rows for UNIQUE records only (exactly 15 columns). No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const now=moscowIsoNow();
const recs=$('Deduplicate Listings').all().map(i=>i.json);
const out=[];
for(const r of recs){
  if(str(r.dedup_status)!=='unique')continue;
  out.push({ json: {
    dedup_key:str(r.dedup_key),
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    author_handle:str(r.seller_name||r.author_handle),
    text_hash:str(r.text_hash),
    first_seen_at:now,
    last_seen_at:now,
    last_route:str(r.predicted_route),
    last_processing_status:'raw_collected',
    last_entity_type:str(r.predicted_entity_type),
    agent_request_id:str($('Set Avito Connector Config').first().json.agent_request_id),
    note:'avito_classifieds_connector_stage_3_3'
  }});
}
return out;

// One agent_requests row (exactly 21 columns). status=completed. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Avito Connector Config').first().json;
const recs=$('Deduplicate Listings').all().map(i=>i.json);
const total=recs.length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const skipped=recs.filter(r=>str(r.predicted_route)==='skipped_log').length;
const queries=Array.isArray(cfg.search_queries)?cfg.search_queries.join('; '):str(cfg.query);
const fixtureMode=(cfg.fixture_mode===true||str(cfg.fixture_mode).toLowerCase()==='true');
return [{ json: {
  agent_request_id:str(cfg.agent_request_id),
  created_at:str(cfg.created_at),
  requested_by:str(cfg.requested_by)||'operator',
  request_text:'Avito/classified competitor discovery: '+queries,
  request_type:str(cfg.request_type)||'classified_competitor_discovery',
  source_scope:'classified_listings',
  platforms:'avito',
  query:queries,
  region:str(cfg.region)||'Москва/МО',
  service_focus:str(cfg.service_focus)||'credit_broker',
  requested_limit:fixtureMode?total:(Number(cfg.max_items)||6),
  status:'completed',
  plan_summary:'Avito/Classifieds listing connector ('+(fixtureMode?'fixture mode':'live Apify mode')+') → raw_market_records for the Touchpoint Analyzer (Workflow 08).',
  estimated_source_cost_usd:0,
  estimated_analysis_cost_usd:0,
  approval_required:false,
  approved_by:'',
  approved_at:'',
  result_summary:'total_items='+total+'; unique='+unique+'; duplicates='+duplicate+'; skipped='+skipped+'.',
  next_action:'Run Workflow 08 on collected raw records manually',
  notes:'No auto-handoff in v0.1. Competitor Ad / Semantic Intelligence connector. Source: '+(fixtureMode?'fixture':'apify_live')+'.'
}}];

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Avito Connector Config').first().json;
const recs=$('Deduplicate Listings').all().map(i=>i.json);
const total=recs.length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const skipped=recs.filter(r=>str(r.predicted_route)==='skipped_log').length;
const predicted_route_counts={};const record_type_counts={};
for(const r of recs){
  const pr=str(r.predicted_route)||'unknown';predicted_route_counts[pr]=(predicted_route_counts[pr]||0)+1;
  const t=str(r.record_type_hint)||'unknown';record_type_counts[t]=(record_type_counts[t]||0)+1;
}
const writeDupAudit=(cfg.write_duplicate_audit===true||str(cfg.write_duplicate_audit).toLowerCase()==='true');
const rawWritten=writeDupAudit?total:unique;
return [{ json: {
  workflow:'09 - Avito Classifieds Listing Connector',
  agent_request_id:str(cfg.agent_request_id),
  run_id:str(cfg.run_id),
  fixture_mode:(cfg.fixture_mode===true||str(cfg.fixture_mode).toLowerCase()==='true'),
  live_mode:(cfg.live_mode===true||str(cfg.live_mode).toLowerCase()==='true'),
  total_items:total,
  unique_count:unique,
  duplicate_count:duplicate,
  skipped_count:skipped,
  raw_market_records_written:rawWritten,
  registry_rows_written:unique,
  predicted_route_counts:predicted_route_counts,
  record_type_counts:record_type_counts,
  next_action:'Inspect raw_market_records, then run Workflow 08 (Touchpoint Analyzer) manually. No auto-handoff. No business-tab writes here.'
}}];
